    // 共享的复制兑底（提升到 DOMContentLoaded 作用域，代码块与表格两处处理器均可调用）
    function fallbackCopy(text, onOk, onFail) {
        var ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        var ok = false;
        try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
        document.body.removeChild(ta);
        if (ok) { if (onOk) onOk(); } else { if (onFail) onFail(); }
    }

    var pres = document.querySelectorAll('.post-content pre');
    pres.forEach(function(pre) {
        // mermaid 块不加按钮（会被 head.html 转成 .mermaid 容器，但保险起见跳过）
        var code = pre.querySelector('code');
        if (code && /language-mermaid/.test(code.className)) return;
        if (pre.querySelector('.code-copy-btn')) return; // 防重复

        var btn = document.createElement('button');
        btn.className = 'code-copy-btn';
        btn.type = 'button';
        btn.textContent = '复制';
        btn.setAttribute('aria-label', '复制代码');

        btn.addEventListener('click', function() {
            var target = pre.querySelector('code') || pre;
            var text = target.innerText || target.textContent || '';
            function done() {
                btn.textContent = '已复制!';
                btn.classList.add('copied');
                setTimeout(function() {
                    btn.textContent = '复制';
                    btn.classList.remove('copied');
                }, 2000);
            }
            function fail() {
                btn.textContent = '复制失败';
                setTimeout(function() { btn.textContent = '复制'; }, 2000);
            }
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(done).catch(function() { fallbackCopy(text, done, fail); });
            } else {
                fallbackCopy(text, done, fail);
            }
        });

        pre.appendChild(btn);
    });

    // ============================================================
    // 表格复制按钮
    // ============================================================
    var tables = document.querySelectorAll('.post-content table');
    tables.forEach(function(table) {
        if (table.dataset.copyDone === '1') return;
        table.dataset.copyDone = '1';
        var wrapper = document.createElement('div');
        wrapper.className = 'table-copy-wrapper';
        table.parentNode.insertBefore(wrapper, table);

        // 滚动容器紧包表格（定位上下文）
        var scroll = document.createElement('div');
        scroll.className = 'table-copy-scroll';
        wrapper.appendChild(scroll);
