.header-publish {
  float: left;
  width: 72px;
  height: 24px;
  line-height: 24px;
  background-color: #ED3F40;
  border-radius: 26px;
  text-align: center;
  font-size: 14px;
  color: #fff;
  margin: 5px 25px 0 0;
  position: relative;
  cursor: pointer;
}

.header-publish :hover .header-publish-hide{
  display: block;
}

.header-publish .iconfont {
  color: #DEDEDE;
  margin: 0 0 0 5px;
}

.header-publish-hide {
  display: none;
  width: 130px;
  background-image: url(../images/toutiao/header-pub-bg.png);
  background-position-x: 2px;
  background-size: 100% 100%;
  position: absolute;
  top: 23px;
  left: -36px;
  z-index: 3;
  padding: 15px 9px;
}

.header-publish-hide a {
  display: block;
  height: 37px;
  width: 134px;
  line-height: 37px;
  font-size: 14px;
  color: #4A4A4A;
  background: #fff;
  text-align: left;
  cursor: pointer;
}

.header-publish-hide a:hover {
  background: #F6F6F6;
}

.header-publish-hide a img {
  width: 13.5px;
}

.header-publish-hide a span {
  vertical-align: middle;
}
