  function watchForUnmount(selector, callback, options = {}) {
    const { root = document.body } = options;

    let element = document.querySelector(selector);
    if (!element) {
      console.warn(`Element ${selector} not found`);
      return () => {};
    }

    let hasCalled = false; // ← Prevents duplicate calls

    const observer = new MutationObserver(() => {
      if (hasCalled) return;

      if (!document.contains(element)) {
        hasCalled = true;
        observer.disconnect();
        callback(element);
      }
    });

    observer.observe(root, {
      childList: true,
      subtree: true,
    });

    // Optional: One-time final safety check
    const safetyCheck = setTimeout(() => {
      if (!hasCalled && !document.contains(element)) {
        hasCalled = true;
        observer.disconnect();
        callback(element);
      }
    }, 1000);

    // Cleanup function
    return () => {
      hasCalled = true;
      observer.disconnect();
      clearTimeout(safetyCheck);
    };
