            /* 🐕 Dog Shake Animation */
            @keyframes slideDogFromLeft {
                from {
                    opacity: 0;
                    transform: translateX(-100px); /* Start hidden down at the dog's bottom */
                }
                to {
                    opacity: 1;
                    transform: translate(0);    /* Slide up to its resting absolute position */
                }
            }

            @keyframes shakeDog {
                0%, 50%, 100% { transform: rotate(0deg) translateX(0); }
                25% { transform: rotate(-15deg) translateX(-2px); }
                75% { transform: rotate(8deg) translateX(0); }
            }

            /* Smooth scaling handling for the widget container on hover */
            .widget-container {
                transition: transform 0.3s ease !important;
            }
            .widget-container:hover {
                transform: scale(1.03);
            }
        `;
    document.head.appendChild(styleTag);

