        message:
          "https://www.three.com.hk/assets/images/message-center-en.png",
      },
    };

    // 3. Selection
    const positions = Object.keys(buttonConfig);
    let choice = positions[Math.floor(Math.random() * positions.length)];

    // Please do not remove or delete!
    // choice = 'left';
    // choice = 'center';

    const settings = buttonConfig[choice];
    const isMobile = window.innerWidth <= 768;

    // 4. Create Container
    const widgetContainer = document.createElement("div");
    widgetContainer.className = "widget-container"; // Assigned class for CSS hover targeting

    // 5. Create Elements
    const btn = document.createElement("button");
    btn.innerHTML = `<img src="${settings.img}" alt="Pet" style="width: 100%; height: auto; display: block;">`;

    const message = document.createElement("div");
    message.innerHTML = `<img src="${settings.message}" alt="Pet Plan Bubble Message" style="width: 100%; height: auto; display: block;">`;

    // 6. Responsive Width Logic
    let btnWidth;
    if (choice === "left") {
      btnWidth = isMobile ? "134px" : "134px";
    } else if (choice === "center") {
      btnWidth = isMobile ? "159px" : "159px";
    } else {
      btnWidth = isMobile ? "200px" : "300px";
    }

    // 7. Core Styles on Container (Acts as the absolute anchor)
    Object.assign(widgetContainer.style, {
      position: "fixed",
      bottom: "0",
      width: btnWidth,
      zIndex: "9999",
    });

    // Horizontal Positioning
    if (choice === "left") {
      widgetContainer.style.left = "0px";
    } else if (choice === "center") {
      widgetContainer.style.left = "0";
      widgetContainer.style.right = "0";
      widgetContainer.style.margin = "0 auto";
    } else {
      widgetContainer.style.right = "20px";
    }

    // Button Styles (Sits normally at the bottom of the container)
    Object.assign(btn.style, {
      width: "100%",
      background: "transparent",
      border: "none",
      padding: "0",
      cursor: "pointer",
      outline: "none",
      position: "relative",
      zIndex: "2", // Sits on top of the message while it slides up
    });

    // Message Bubble Styles
    Object.assign(message.style, {
      opacity: "0",
      position: "absolute",
      width: "100%", // Inherits container width match
      transition: "transform 0.3s ease",
      pointerEvents: "pointer",
      zIndex: "1", // Hidden behind dog graphic layers initially
    });

    // --- Fixed horizontal adjustment for the 'left' layout choice ---
    if (choice === "left") {
      // Dog slides in from left + fades in for 0.8s
      btn.style.animation = "slideDogFromLeft 0.8s ease-in-out forwards";
      message.style.left = "80px"; // Changed from right = '-80px' to consistently push it rightward

      // Message Bubble Styles
      Object.assign(message.style, {
        width: "250px",
        bottom: "80%", // Sits above the dog vertically in its resting state
      });

      // Listen for slide animation to complete, then start shake
      btn.addEventListener("animationend", function handleSlideComplete(e) {
        if (e.animationName === "slideDogFromLeft") {
          btn.removeEventListener("animationend", handleSlideComplete);
          btn.style.animation = "none";
          void btn.offsetWidth; // Force reflow
          btn.style.animation = "shakeDog .3s ease-in-out forwards";

          // Listen for shake animation to complete, then start message animation
          btn.addEventListener("animationend", function handleShakeComplete(e) {
            if (e.animationName === "shakeDog") {
              btn.removeEventListener("animationend", handleShakeComplete);
              message.style.animation =
                "slideFromBehindDog 0.8s cubic-bezier(0.25, 1, 0.5, 1) forwards";
            }
          });
        }
      });
    } else if (choice === "center") {
      // Dog slides in from bottom + fades in for 0.8s
      btn.style.animation = "slideFromBehindDog 0.8s ease-in-out forwards";
      message.style.left = "0";

      // Vertically align message and dog for center choice
      Object.assign(widgetContainer.style, {
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-end",
      });

      Object.assign(message.style, {
        position: "static",
        width: "327px",
