        marginTop: "0",
        marginBottom: "-30px",
        textAlign: "center",
      });

      // Listen for slide animation to complete, then start shake
      btn.addEventListener("animationend", function handleSlideComplete(e) {
        if (e.animationName === "slideFromBehindDog") {
          btn.removeEventListener("animationend", handleSlideComplete);
          btn.style.animation = "none";
          void btn.offsetWidth; // Force reflow
          btn.style.animation = "shakeDog .3s ease-in-out forwards";

          // Listen for shake animation to complete, then start message animation
          btn.addEventListener("animationend", function handleShakeComplete(e) {
            if (e.animationName === "shakeDog") {
              btn.removeEventListener("animationend", handleShakeComplete);
              message.style.animation =
                "slideFromBehindDog 0.8s cubic-bezier(0.25, 1, 0.5, 1) forwards";
            }
          });
        }
      });
    } else {
      message.style.left = "0"; // Default fallback centering for non-left choice layouts
    }

    // 8. Interaction Logic (Hover Bubble Push)
    if (!isMobile) {
      widgetContainer.onmouseover = () => {
        message.style.transform = "translateY(-10px)"; // Lifts the text bubble slightly on hover
      };
      widgetContainer.onmouseout = () => {
        message.style.transform = "translateY(0)";
      };
    }

    // 9. Open Link & Mount
    widgetContainer.onclick = () => window.open(settings.url, "_blank");
    widgetContainer.style.cursor = "pointer";

    // Append items
    if (choice === "center") {
      // For center: append message first so it appears above the dog
      widgetContainer.appendChild(message);
      widgetContainer.appendChild(btn);
    } else {
      // For left/right: append button first
      widgetContainer.appendChild(btn);
      widgetContainer.appendChild(message);
    }
    document.body.appendChild(widgetContainer);
  }

  function watchForUnmount(selector, callback, options = {}) {
    const { root = document.body } = options;

    let element = document.querySelector(selector);
    if (!element) {
      console.warn(`Element ${selector} not found`);
      return () => {};
    }

    let hasCalled = false; // ← Prevents duplicate calls

    const observer = new MutationObserver(() => {
      if (hasCalled) return;

      if (!document.contains(element)) {
        hasCalled = true;
        observer.disconnect();
        callback(element);
      }
    });

    observer.observe(root, {
      childList: true,
      subtree: true,
    });

    // Optional: One-time final safety check
    const safetyCheck = setTimeout(() => {
      if (!hasCalled && !document.contains(element)) {
        hasCalled = true;
        observer.disconnect();
        callback(element);
      }
    }, 1000);

    // Cleanup function
    return () => {
      hasCalled = true;
      observer.disconnect();
      clearTimeout(safetyCheck);
    };
  }





